package com.hotel.booking.dao;
import com.hotel.booking.config.DBConnection; import com.hotel.booking.model.Room; import java.sql.*; import java.util.*; import java.math.BigDecimal;
public class RoomDAO {
 public Room add(Room r)throws SQLException {try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO rooms(room_number,room_type,price_per_night,status) VALUES(?,?,?,'AVAILABLE')",Statement.RETURN_GENERATED_KEYS)){p.setString(1,r.getRoomNumber());p.setString(2,r.getRoomType());p.setBigDecimal(3,r.getPricePerNight());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){if(k.next())return new Room(k.getInt(1),r.getRoomNumber(),r.getRoomType(),r.getPricePerNight(),"AVAILABLE");}}return r;}
 public List<Room> all()throws SQLException{return query("SELECT * FROM rooms ORDER BY id");} public List<Room> available()throws SQLException{return query("SELECT * FROM rooms WHERE status='AVAILABLE' ORDER BY id");}
 private List<Room> query(String sql)throws SQLException {List<Room> list=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){while(r.next())list.add(new Room(r.getInt("id"),r.getString("room_number"),r.getString("room_type"),r.getBigDecimal("price_per_night"),r.getString("status")));}return list;}
 public boolean setStatus(int id,String status)throws SQLException {try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE rooms SET status=? WHERE id=?")){p.setString(1,status);p.setInt(2,id);return p.executeUpdate()>0;}}
 public Room byId(int id)throws SQLException {try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM rooms WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next())return new Room(r.getInt("id"),r.getString("room_number"),r.getString("room_type"),r.getBigDecimal("price_per_night"),r.getString("status"));}}return null;}
}
